    public static bool TentarLer<T>(string? texto, out T valor)
        where T : struct, Enum
    {
        foreach (var candidato in Enum.GetValues<T>())
        {
            if (De(candidato) == texto)
            {
                valor = candidato;
                return true;
            }
        }

        valor = default;
        return false;
    }
}

