    public static bool SoPorTextoLivre(ItemPremioParticipacao item)
    {
        ArgumentNullException.ThrowIfNull(item);
        return item.ChaveDeDeduplicacao.Contains(CampoDeDeduplicacao.Materia);
    }

    public bool Aceita(ItemPremioParticipacao item)
    {
        ArgumentNullException.ThrowIfNull(item);

        return Origem == OrigemDoEvento.TextoLivre
            ? true
            : !SoPorTextoLivre(item) && _itensAceitos.Contains(item.Codigo, StringComparer.Ordinal);
    }

    public bool AbertoAoCurso(Guid? cursoId) => CursoId is null || CursoId == cursoId;

    // Quando o evento pode ser reivindicado (produto.md 4.6): já começou, em São Paulo, e não
    // começou antes do semestre letivo vigente. O ranking corta por semestre letivo, e uma
    // reivindicação retroativa pontuaria num semestre a que não pertence. Fora de semestre
    // vigente (recesso), nenhum evento é reivindicável. O fim pode estar adiante: a
    // atividade de duração é reivindicada enquanto corre, e o aprovador julga.
    public RecusaDoEvento? RecusaParaReivindicarEm(DateOnly hoje, SemestreLetivo? vigente)
    {
        if (vigente is null || !vigente.Contem(hoje))
        {
            return RecusaDoEvento.ForaDeSemestreVigente;
        }

        if (Inicio > hoje)
        {
            return RecusaDoEvento.NaoComecou;
        }

        return Inicio < vigente.Inicio ? RecusaDoEvento.AnteriorAoSemestre : null;
    }
}

public enum OrigemDoEvento
{
    Semeado,
    TextoLivre,
}

public enum RecusaDoEvento
{
    ForaDeSemestreVigente,
    NaoComecou,
    AnteriorAoSemestre,
}

