// chave de deduplicação. A medalha, quem concedeu e quando, a notificação e o recálculo de
// raridade gravam juntos.
public sealed class ConcederMedalhaHandler(
    IEscopoDeTurma escopo,
    IUsuarioRepository usuarios,
