namespace Maxx.Application;

// Um pedido que a aplicação recusa por regra, não por falha: a borda traduz o tipo em
// status HTTP e devolve o código no formato único de erro. A mensagem é só para o log.
public sealed class RecusaException : Exception
{
    public RecusaException()
    {
        Codigo = string.Empty;
    }

    public RecusaException(string message) : base(message)
    {
        Codigo = string.Empty;
    }

    public RecusaException(string message, Exception innerException) : base(message, innerException)
    {
        Codigo = string.Empty;
    }

    public RecusaException(TipoDeRecusa tipo, string codigo, string? motivoParaLog = null)
        : base(motivoParaLog ?? codigo)
    {
        Tipo = tipo;
        Codigo = codigo;
    }

    public TipoDeRecusa Tipo { get; }

    // Estável e em kebab-case: é o que o cliente usa para escolher a mensagem amigável.
    public string Codigo { get; }
}

public enum TipoDeRecusa
{
    Invalido,
    NaoEncontrado,
    Conflito,
    NaoAutorizado,

    // Autenticado, mas sem direito sobre o recurso: o escopo de turma do professor.
    Proibido,
}

// Gravação recusada por uma unicidade do banco: a corrida que a checagem prévia não
// consegue fechar sozinha.
public sealed class ConflitoDeUnicidadeException : Exception
{
    public ConflitoDeUnicidadeException()
    {
    }

    public ConflitoDeUnicidadeException(string message) : base(message)
    {
    }

    public ConflitoDeUnicidadeException(string message, Exception innerException) : base(message, innerException)
    {
    }

    public ConflitoDeUnicidadeException(Unicidade unicidade, Exception innerException)
        : base($"Unicidade violada: {unicidade}.", innerException)
    {
        Unicidade = unicidade;
    }

    public Unicidade Unicidade { get; }
}

public enum Unicidade
{
    Outra,
    ContaPorCadastro,
    Prefixo,

    // Duas medalhas ativas com a mesma chave de deduplicação: a mesma vaga do período.
    MedalhaAtiva,

    // Dois posts não removidos para o mesmo prêmio: um prêmio rende um post.
    PostPorPremio,

    // A mesma pessoa curtindo o mesmo post duas vezes ao mesmo tempo.
    Curtida,

    // O mesmo seguimento gravado duas vezes ao mesmo tempo.
    Seguimento,
}

// Gravação recusada porque a linha mudou desde a leitura (xmin): outro pedido chegou
// antes. Quem chama decide se relê e tenta de novo.
public sealed class ConflitoDeConcorrenciaException : Exception
{
    public ConflitoDeConcorrenciaException()
    {
    }

    public ConflitoDeConcorrenciaException(string message) : base(message)
    {
    }

    public ConflitoDeConcorrenciaException(string message, Exception innerException) : base(message, innerException)
    {
    }
}

public interface IUnitOfWork
{
    // Lança ConflitoDeUnicidadeException quando o banco recusa por unicidade e
    // ConflitoDeConcorrenciaException quando a linha mudou desde a leitura.
    Task SalvarAsync(CancellationToken cancellationToken);

    // Esquece o que o escopo leu e alterou, para reler do banco.
    void Descartar();
}
using Maxx.Application.Medalhas;
using Maxx.Domain.Academico;
using Maxx.Domain.Catalogo;
using Maxx.Domain.Identidade;
using Maxx.Domain.Premios;
using Maxx.Infrastructure.Persistence;
using Maxx.Infrastructure.Seed;
using Microsoft.EntityFrameworkCore;

namespace Maxx.Infrastructure.Medalhas;

internal sealed class MedalhaRepository(MaxxDbContext db) : IMedalhaRepository
{
    private static readonly string _tipoMedalha = NomeJson.De(TipoDeItem.Medalha);

    public void Adicionar(Medalha medalha) => db.Add(medalha);

    public Task<Medalha?> BuscarAsync(Guid id, CancellationToken cancellationToken) =>
        db.Set<Medalha>().SingleOrDefaultAsync(medalha => medalha.Id == id, cancellationToken);

    public async Task<IReadOnlyList<Medalha>> DoAlunoNoItemAsync(Guid alunoId, string itemCodigo, CancellationToken cancellationToken) =>
        await db.Set<Medalha>()
            .Where(medalha => medalha.AlunoId == alunoId && medalha.ItemCodigo == itemCodigo)
            .ToListAsync(cancellationToken);

    public async Task<ItemDeMedalha?> ItemAsync(string codigo, CancellationToken cancellationToken)
    {
        var row = await db.Set<ItemCatalogoRow>().AsNoTracking()
            .SingleOrDefaultAsync(item => item.Codigo == codigo && item.Tipo == _tipoMedalha, cancellationToken);
        return row is null ? null : new ItemDeMedalha(CatalogoRowMapper.ParaMedalha(row), row.Versao);
    }

    public async Task<TurmaDaConcessao?> TurmaAsync(Guid turmaId, CancellationToken cancellationToken)
    {
        var turma = await db.Set<Turma>().Include(turma => turma.Materia)
            .SingleOrDefaultAsync(turma => turma.Id == turmaId, cancellationToken);
        if (turma is null)
        {
            return null;
        }

        var semestre = await db.Set<SemestreLetivo>().Include(semestre => semestre.Bimestres)
            .SingleAsync(semestre => semestre.Id == turma.SemestreLetivoId, cancellationToken);
        return new TurmaDaConcessao(turma, semestre);
    }

    public async Task<AlunoDaConcessao?> AlunoMatriculadoAsync(Guid turmaId, Guid alunoId, CancellationToken cancellationToken)
    {
        var encontrado = await (
                from usuario in db.Set<Usuario>()
                join cadastro in db.Set<CadastroElegivel>() on usuario.CadastroElegivelId equals cadastro.Id
                join curso in db.Set<Curso>() on cadastro.CursoId equals curso.Id
                where usuario.Id == alunoId
                    && usuario.Papeis == Papeis.Aluno
                    && db.Set<Matricula>().Any(matricula => matricula.AlunoId == cadastro.Id && matricula.TurmaId == turmaId)
                select new { usuario, curso.Sigla })
            .SingleOrDefaultAsync(cancellationToken);
        return encontrado is null ? null : new AlunoDaConcessao(encontrado.usuario, encontrado.Sigla);
    }
}
import { readdirSync, readFileSync } from "fs";
import { join } from "path";

import {
  codigoDoErro,
  codigosConhecidos,
  mensagemDaFalha,
  mensagemDeErro,
} from "./erros";

const API = join(__dirname, "../../../api/src");

// Os arquivos de códigos de recusa da Application (CodigosDeRecusa.cs,
// CodigosDaMedalha.cs, ...), onde quer que estejam: código novo num arquivo novo também
// precisa de mensagem.
function arquivosDeCodigos(): string[] {
  const raiz = join(API, "Maxx.Application");
  return readdirSync(raiz, { recursive: true, encoding: "utf8" })
    .filter((caminho) => /(^|[\\/])Codigos\w*\.cs$/.test(caminho))
    .map((caminho) => join(raiz, caminho));
}

// Os códigos que a API pode mandar, lidos do próprio código dela.
function codigosDaApi(): string[] {
  const recusas = arquivosDeCodigos()
    .map((arquivo) => readFileSync(arquivo, "utf8"))
    .join("\n");
  const erros = readFileSync(
    join(API, "Maxx.Api/Erros/DomainExceptionHandler.cs"),
    "utf8",
  );
  const literais = (texto: string, padrao: RegExp) =>
    [...texto.matchAll(padrao)].map((m) => m[1]!);

  return [
    ...literais(recusas, /const string \w+ = "([a-z-]+)";/g),
    ...literais(erros, /=> "([a-z-]+)"/g),
  ];
}

