    private async Task<MaxxApiFactory> MundoAsync(DateTimeOffset agora)
    {
        var factory = new MaxxApiFactory(
            await postgres.CreateDatabaseAsync(),
            servicos: colecao => colecao.Replace(ServiceDescriptor.Singleton<TimeProvider>(new RelogioDeTeste(agora))));
        await factory.MigrateAsync(Ct);
        await factory.SeedBaseAsync(Ct);
        await factory.SeedDemoAsync(Ct);

        await using var scope = factory.Services.CreateAsyncScope();
        var db = scope.ServiceProvider.GetRequiredService<MaxxDbContext>();
        var hash = new Argon2idSenhaHasher().Hash(Senha);
