                where cadastro.Email == RenataProfessora
                select usuario)
            .SingleAsync(Ct);
        renata.DefinirSenha(hash);
        await db.SaveChangesAsync(Ct);

        return factory;
    }

    private static async Task<HttpClient> ComoAsync(MaxxApiFactory factory, string email)
    {
        var client = factory.CreateClient();
        var resposta = await client.PostAsJsonAsync(
            new Uri("/api/v1/auth/login", UriKind.Relative), new { identificador = email, senha = Senha }, Ct);
