11	// instituição grava quem e quando juntos.
12	internal sealed class PostConfiguration : IEntityTypeConfiguration<Post>
13	{
14	    public void Configure(EntityTypeBuilder<Post> builder)
15	    {
16	        builder.ToTable("post", table =>
17	        {
18	            table.HasCheckConstraint(
19	                "ck_post_nao_vazio", "legenda IS NOT NULL OR chave_da_foto_do_feed IS NOT NULL OR medalha_id IS NOT NULL");
20	            table.HasCheckConstraint(
21	                "ck_post_foto_completa", "(chave_da_foto_do_feed IS NULL) = (chave_da_foto_da_grade IS NULL)");
22	            table.HasCheckConstraint("ck_post_remocao", "(removido_em IS NULL) = (removido_por_id IS NULL)");
23	        });
24	        builder.HasKey(post => post.Id);
25	        builder.Property(post => post.Id).ValueGeneratedNever();
26	
27	        // Um prêmio rende um post. O removido pela instituição sai do índice: o aluno pode
28	        // postar o prêmio de novo, como depois de apagar.
29	        builder.HasIndex(post => post.MedalhaId)
30	            .HasDatabaseName("ix_post_medalha_ativa")
31	            .IsUnique()
32	            .HasFilter("medalha_id IS NOT NULL AND removido_em IS NULL");
33	
34	        // Os posts de um autor, do mais novo ao mais antigo: o perfil e o trecho de seguidos
35	        // do feed (passo 7, etapas 5 e 6) andam por este índice.
36	        builder.HasIndex(post => new { post.AutorId, post.CriadoEm, post.Id })
37	            .IsDescending(false, true, true);
38	
39	        builder.HasOne<Usuario>().WithMany().HasForeignKey(post => post.AutorId).OnDelete(DeleteBehavior.Restrict);
40	        builder.HasOne<Usuario>().WithMany().HasForeignKey(post => post.RemovidoPorId).OnDelete(DeleteBehavior.Restrict);
41	        builder.HasOne<Medalha>().WithMany().HasForeignKey(post => post.MedalhaId).OnDelete(DeleteBehavior.Restrict);
42	
43	        // Duas remoções, ou remoção e anulação, ao mesmo tempo: o xmin deixa só a primeira
44	        // gravar.
45	        builder.Property<uint>("Versao").IsRowVersion();
46	
47	        builder.Ignore(post => post.TemFoto);
48	        builder.Ignore(post => post.TemLegenda);
49	        builder.Ignore(post => post.TemPremio);

