[Fact]
public void Contestado_vai_a_averiguacao_para_de_pontuar_e_prende_o_post()
{
    var premio = Aprovado();
    var renata = Renata();

    var resultado = premio.Contestar(renata, "  A foto é de outro evento.  ", _agora.AddDays(3));

