1	// Textos e datas do prêmio de participação. As datas vão para a API em ISO (aaaa-mm-dd) e
2	// aparecem para o aluno em dd/mm, como no resto do app.
3	
4	// "dd/mm/aaaa", com ou sem zero à esquerda, numa data que existe; nulo se não for.
5	export function lerData(texto: string): string | null {
6	  const partes = /^\s*(\d{1,2})\/(\d{1,2})\/(\d{4})\s*$/.exec(texto);
7	  if (!partes) return null;
8	  const [dia, mes, ano] = [
9	    Number(partes[1]),
10	    Number(partes[2]),
11	    Number(partes[3]),
12	  ];
13	  const data = new Date(Date.UTC(ano, mes - 1, dia));
14	  if (
15	    data.getUTCFullYear() !== ano ||
16	    data.getUTCMonth() !== mes - 1 ||
17	    data.getUTCDate() !== dia
18	  ) {
19	    return null;
20	  }
21	  return `${ano}-${String(mes).padStart(2, "0")}-${String(dia).padStart(2, "0")}`;
22	}
23	
24	// "14/09" de "2026-09-14".
25	export function diaEMes(iso: string): string {
26	  const [, mes, dia] = iso.slice(0, 10).split("-");
27	  return `${dia}/${mes}`;
28	}
29	
30	// "14/09" para um dia só, "14/09 a 18/09" para um período.
31	export function periodo(inicio: string, fim: string): string {
32	  return inicio === fim
33	    ? diaEMes(inicio)
34	    : `${diaEMes(inicio)} a ${diaEMes(fim)}`;
35	}
