      testID="faixa"
      style={[styles.faixa, { backgroundColor: colors.surface }]}
    >
      <Medalhao tier={tier} glifo={glifo} raridade={raridade ?? undefined} />

      <View style={styles.textos}>
        {rotulo && (
          <Text style={[textStyles.rotulo, { color: colors.ink2 }]}>
            {rotulo}
