            accessibilityLabel={curtida.curtiu ? "Descurtir" : "Curtir"}
            aria-pressed={curtida.curtiu}
            onPress={alternarCurtida}
            style={styles.botaoDeIcone}
          >
            <Icon
              name="heart"
              size={tamanhos.iconeNav}
              filled={curtida.curtiu}
