// TEMPORÁRIO, fora do commit: capturas da etapa 5 do passo 8 para a revisão do autor.
import { readFileSync, writeFileSync } from "node:fs";

import { expect, test, type APIRequestContext, type Page } from "@playwright/test";

import { novaConta, sql, type Aluno } from "./apoio/contas";
import { linkDeRecuperacao } from "./apoio/mailpit";
import { matricular, novaProfessora } from "./apoio/medalhas";

const SAIDA = process.env.CAPTURAS!;

async function foto(page: Page, caminho: string, lado: number, cor: string) {
  await page.setContent(`<canvas id=c width=${lado} height=${lado}></canvas>`);
  const base64 = await page.evaluate(
    ({ lado, cor }) => {
      const canvas = document.getElementById("c") as HTMLCanvasElement;
      const contexto = canvas.getContext("2d")!;
      const ceu = contexto.createLinearGradient(0, 0, 0, lado);
      ceu.addColorStop(0, cor);
      ceu.addColorStop(1, "#0b2a55");
      contexto.fillStyle = ceu;
      contexto.fillRect(0, 0, lado, lado);
      contexto.fillStyle = "#f5b400";
      contexto.beginPath();
      contexto.arc(lado / 2, lado / 2, lado / 5, 0, Math.PI * 2);
      contexto.fill();
      return canvas.toDataURL("image/jpeg", 0.85).split(",")[1];
    },
    { lado, cor },
  );
  writeFileSync(caminho, Buffer.from(base64!, "base64"));
}

async function token(request: APIRequestContext, identificador: string, senha: string) {
  const resposta = await request.post("/api/v1/auth/login", { data: { identificador, senha } });
  expect(resposta.status()).toBe(200);
  return (await resposta.json()).accessToken as string;
}

const comToken = (t: string) => ({ Authorization: `Bearer ${t}` });

// Upload de verdade: pede a assinatura e faz os dois PUTs no emulador.
async function upload(request: APIRequestContext, t: string, feed: string, grade: string) {
  const bytesFeed = readFileSync(feed);
  const bytesGrade = readFileSync(grade);
  const pedido = await request.post("/api/v1/uploads", {
    headers: comToken(t),
    data: { finalidade: "post", tipoDeConteudo: "image/jpeg", tamanhoDoFeed: bytesFeed.length, tamanhoDaGrade: bytesGrade.length },
  });
  expect(pedido.status()).toBe(201);
  const assinado = await pedido.json();
  for (const [envio, bytes] of [[assinado.feed, bytesFeed], [assinado.grade, bytesGrade]] as const) {
    const put = await fetch(envio.url, { method: "PUT", headers: { "Content-Type": "image/jpeg" }, body: bytes });
    expect(put.status).toBe(200);
  }
  return assinado.id as string;
}

async function reivindicar(request: APIRequestContext, t: string, corpo: object) {
  const resposta = await request.post("/api/v1/reivindicacoes", { headers: comToken(t), data: corpo });
  expect(resposta.status(), await resposta.text()).toBe(201);
  const post = await resposta.json();
  return { postId: post.id as string, premioId: post.premio.id as string };
}

const comprovacao = (premioId: string) => sql(`SELECT id FROM comprovacao WHERE premio_participacao_id = '${premioId}';`);

async function entrar(page: Page, aluno: Aluno) {
  await page.goto("/login");
  await page.getByLabel("RA ou e-mail").fill(aluno.ra);
  await page.getByLabel("Senha", { exact: true }).fill(aluno.senha);
  await page.getByRole("button", { name: "Entrar", exact: true }).click();
}

test("capturas da reivindicação", { tag: "@celular" }, async ({ page, request }, info) => {
  test.setTimeout(180_000);
  const tema = info.project.name.replace("celular-", "");
  const aluno = await novaConta(request, "Ana Souza");
  const professora = await novaProfessora(request);
  matricular(aluno, professora.turmaId);

  // A instituição do seed, com senha pelo primeiro acesso.
  const instituicao = "coordenacao@unieduk.com.br";
  const senhaDaInstituicao = `senha-inst-${Date.now()}`;
  await request.post("/api/v1/auth/recuperacao", { data: { email: instituicao } });
  const link = await linkDeRecuperacao(request, instituicao);
  await request.post("/api/v1/auth/recuperacao/confirmar", {
    data: { token: new URL(link).hash.replace("#token=", ""), senha: senhaDaInstituicao },
  });

  const doAluno = await token(request, aluno.ra, aluno.senha);
  const daProfessora = await token(request, professora.email, professora.senha);
  const daInstituicao = await token(request, instituicao, senhaDaInstituicao);

  const feed = info.outputPath("feed.jpg");
  const grade = info.outputPath("grade.jpg");
  await foto(page, feed, 1080, "#8ec5ff");
  await foto(page, grade, 320, "#8ec5ff");
  const outraFeed = info.outputPath("outra-feed.jpg");
  const outraGrade = info.outputPath("outra-grade.jpg");
  await foto(page, outraFeed, 1080, "#c9a6ff");
  await foto(page, outraGrade, 320, "#c9a6ff");

  // Em averiguação: aprovada pela professora e contestada por ela.
  const averiguacao = await reivindicar(request, doAluno, {
    item: "P01",
    eventoDigitado: { nome: "Palestra de LGPD", inicio: "2026-11-03", fim: "2026-11-03" },
    uploadId: await upload(request, doAluno, outraFeed, outraGrade),
    legenda: "Palestra sobre dados pessoais.",
  });
  expect((await request.post(`/api/v1/comprovacoes/${comprovacao(averiguacao.premioId)}/aprovacao`, { headers: comToken(daProfessora) })).status()).toBe(204);
  expect((await request.post(`/api/v1/premios-participacao/${averiguacao.premioId}/contestacao`, { headers: comToken(daProfessora), data: { motivo: "A foto não mostra a palestra." } })).status()).toBe(201);

  // Reprovada, com motivo.
  const reprovada = await reivindicar(request, doAluno, {
    item: "P01",
    eventoDigitado: { nome: "Palestra de carreira", inicio: "2026-11-04", fim: "2026-11-04" },
    uploadId: await upload(request, doAluno, feed, grade),
  });
  expect((await request.post(`/api/v1/comprovacoes/${comprovacao(reprovada.premioId)}/reprovacao`, { headers: comToken(daProfessora), data: { motivo: "A foto não mostra a palestra." } })).status()).toBe(204);

  // Revogada pela instituição, depois da contestação.
  const eventos = await (await request.get("/api/v1/eventos?item=P03", { headers: comToken(doAluno) })).json();
  const revogada = await reivindicar(request, doAluno, {
    item: "P03",
    eventoId: eventos[0].id,
    uploadId: await upload(request, doAluno, feed, grade),
  });
  expect((await request.post(`/api/v1/comprovacoes/${comprovacao(revogada.premioId)}/aprovacao`, { headers: comToken(daProfessora) })).status()).toBe(204);
  const contestacao = await request.post(`/api/v1/premios-participacao/${revogada.premioId}/contestacao`, { headers: comToken(daProfessora), data: { motivo: "Revi a foto." } });
  expect((await request.post(`/api/v1/contestacoes/${(await contestacao.json()).id}/revogacao`, { headers: comToken(daInstituicao), data: { motivo: "A foto é de outro evento." } })).status()).toBe(204);

  // A pendente, pela tela do novo post, no modo de reivindicação.
  await page.setViewportSize({ width: 390, height: 1700 });
  await entrar(page, aluno);
  await page.getByRole("button", { name: "Novo post" }).first().click();
  await page.getByRole("radio", { name: "Reivindicar prêmio" }).click();
  const seletor = page.waitForEvent("filechooser");
  await page.getByRole("button", { name: "Escolher foto" }).click();
  await (await seletor).setFiles(feed);
  await expect(page.getByTestId("previa-da-foto")).toBeVisible();
  await page.getByLabel("Legenda").fill("Semana acadêmica de Computação!");
  await page.getByRole("radio", { name: /^Semana acadêmica/ }).click();
  await page.getByRole("radio", { name: /Semana Acadêmica de Ciência da Computação/ }).click();
  await page.evaluate(() => window.scrollTo(0, 0));
  await page.screenshot({ path: `${SAIDA}/novo-post-reivindicacao-${tema}.png` });
  await page.getByRole("button", { name: "Reivindicar", exact: true }).click();

  // O cartão pendente, no feed.
  await page.setViewportSize({ width: 390, height: 844 });
  const cartao = page.locator('[data-testid^="post-"]', { hasText: "Semana acadêmica de Computação!" });
  await expect(cartao.getByTestId("marca-reivindicado")).toBeVisible();
  await expect.poll(() => cartao.getByTestId("foto-do-post").locator("img").evaluate((img: HTMLImageElement) => img.naturalWidth)).toBeGreaterThan(0);
  await cartao.screenshot({ path: `${SAIDA}/cartao-pendente-${tema}.png` });

  // O cartão em averiguação, para a própria aluna.
  await page.goto(`/post/${averiguacao.postId}`);
  const emAveriguacao = page.locator(`[data-testid="post-${averiguacao.postId}"]`);
  await expect(emAveriguacao.getByTestId("marca-emAveriguacao")).toBeVisible();
  await expect.poll(() => emAveriguacao.getByTestId("foto-do-post").locator("img").evaluate((img: HTMLImageElement) => img.naturalWidth)).toBeGreaterThan(0);
  await emAveriguacao.screenshot({ path: `${SAIDA}/cartao-averiguacao-${tema}.png` });

  // A seção Reivindicações em Troféus.
  await page.goto("/trofeus");
  await page.setViewportSize({ width: 390, height: 1100 });
  await expect(page.getByRole("heading", { name: "Reivindicações" })).toBeVisible();
  await page.screenshot({ path: `${SAIDA}/trofeus-reivindicacoes-${tema}.png` });
});

