    await renderComApi(<ComprovacoesScreen />, api);

    await apertar("Aprovar a comprovação de Ana");

    expect(await screen.findByText("Outra pessoa já decidiu essa comprovação.")).toBeOnTheScreen();
  });

  it("reprovar abre a folha, exige o motivo e manda o motivo aparado", async () => {
    await renderComApi(<ComprovacoesScreen />, api);

    await apertar("Reprovar a comprovação de Ana");
    const folha = await screen.findByRole("dialog", { name: "Reprovar comprovação" });
    expect(within(folha).getByRole("button", { name: "Reprovar" })).toBeDisabled();

    await act(async () => {
      fireEvent.changeText(within(folha).getByLabelText("Motivo"), "  A foto não mostra o evento.  ");
    });
    await act(async () => {
      fireEvent.press(within(folha).getByRole("button", { name: "Reprovar" }));
    });

    expect(await (reprovacao.mock.calls[0]![0] as Request).clone().json()).toEqual({
      motivo: "A foto não mostra o evento.",
    });
  });

  it("recusa da reprovação fica dentro da folha", async () => {
    reprovacao.mockResolvedValue(json(400, { status: 400, codigo: "motivo-invalido" }));
    await renderComApi(<ComprovacoesScreen />, api);

    await apertar("Reprovar a comprovação de Ana");
    const folha = await screen.findByRole("dialog", { name: "Reprovar comprovação" });
    await act(async () => {
      fireEvent.changeText(within(folha).getByLabelText("Motivo"), "Não.");
    });
    await act(async () => {
      fireEvent.press(within(folha).getByRole("button", { name: "Reprovar" }));
    });

    expect(await within(folha).findByText("Escreva o motivo, com até 500 caracteres.")).toBeOnTheScreen();
  });

  it("sem nada pendente, um estado vazio", async () => {
    fila.mockResolvedValue(json(200, { itens: [], proximo: null }));
    await renderComApi(<ComprovacoesScreen />, api);

    expect(await screen.findByText("Nenhuma comprovação pendente.")).toBeOnTheScreen();
  });

  it("aluno não tem fila", async () => {
    eu = { ...PROFESSORA, papeis: ["aluno"] };
    await renderComApi(<ComprovacoesScreen />, api);

    expect(await screen.findByText("Comprovações são para quem aprova.")).toBeOnTheScreen();
  });

  it("o menu do perfil da professora leva às comprovações", async () => {
    await renderComApi(<MenuDoPerfil aberto professor onFechar={jest.fn()} />, api);

    await apertar("Comprovações");

    expect(mockRoteador.push).toHaveBeenCalledWith("/comprovacoes");
  });
});

