// TEMPORÁRIO, fora do commit: capturas da etapa 6 do passo 8 para a revisão do autor.
import { readFileSync, writeFileSync } from "node:fs";

import { expect, test, type APIRequestContext, type Page } from "@playwright/test";

import { novaConta, sql } from "./apoio/contas";
import { matricular, novaProfessora } from "./apoio/medalhas";

const SAIDA = process.env.CAPTURAS!;

async function foto(page: Page, caminho: string, lado: number, cor: string) {
  await page.setContent(`<canvas id=c width=${lado} height=${lado}></canvas>`);
  const base64 = await page.evaluate(
    ({ lado, cor }) => {
      const canvas = document.getElementById("c") as HTMLCanvasElement;
      const contexto = canvas.getContext("2d")!;
      const ceu = contexto.createLinearGradient(0, 0, 0, lado);
      ceu.addColorStop(0, cor);
      ceu.addColorStop(1, "#0b2a55");
      contexto.fillStyle = ceu;
      contexto.fillRect(0, 0, lado, lado);
      contexto.fillStyle = "#f5b400";
      contexto.beginPath();
      contexto.arc(lado / 2, lado / 2, lado / 5, 0, Math.PI * 2);
      contexto.fill();
      return canvas.toDataURL("image/jpeg", 0.85).split(",")[1];
    },
    { lado, cor },
  );
  writeFileSync(caminho, Buffer.from(base64!, "base64"));
}

async function token(request: APIRequestContext, identificador: string, senha: string) {
  const resposta = await request.post("/api/v1/auth/login", { data: { identificador, senha } });
  expect(resposta.status()).toBe(200);
  return (await resposta.json()).accessToken as string;
}

const comToken = (t: string) => ({ Authorization: `Bearer ${t}` });

async function upload(request: APIRequestContext, t: string, feed: string, grade: string) {
  const bytesFeed = readFileSync(feed);
  const bytesGrade = readFileSync(grade);
  const pedido = await request.post("/api/v1/uploads", {
    headers: comToken(t),
    data: { finalidade: "post", tipoDeConteudo: "image/jpeg", tamanhoDoFeed: bytesFeed.length, tamanhoDaGrade: bytesGrade.length },
  });
  expect(pedido.status()).toBe(201);
  const assinado = await pedido.json();
  for (const [envio, bytes] of [[assinado.feed, bytesFeed], [assinado.grade, bytesGrade]] as const) {
    const put = await fetch(envio.url, { method: "PUT", headers: { "Content-Type": "image/jpeg" }, body: bytes });
    expect(put.status).toBe(200);
  }
  return assinado.id as string;
}

async function reivindicar(request: APIRequestContext, t: string, corpo: object) {
  const resposta = await request.post("/api/v1/reivindicacoes", { headers: comToken(t), data: corpo });
  expect(resposta.status(), await resposta.text()).toBe(201);
  return (await resposta.json()).premio.id as string;
}

test("capturas da fila de comprovações", { tag: "@celular" }, async ({ page, request }, info) => {
  test.setTimeout(180_000);
  const tema = info.project.name.replace("celular-", "");
  const professora = await novaProfessora(request);
  const ana = await novaConta(request, "Ana Souza");
  const bruno = await novaConta(request, "Bruno Lima");
  const carla = await novaConta(request, "Carla Dias");
  for (const aluno of [ana, bruno, carla]) matricular(aluno, professora.turmaId);

  const cores = ["#8ec5ff", "#c9a6ff", "#9be3b0"];
  const fotos: [string, string][] = [];
  for (const [i, cor] of cores.entries()) {
    const feed = info.outputPath(`feed-${i}.jpg`);
    const grade = info.outputPath(`grade-${i}.jpg`);
    await foto(page, feed, 1080, cor);
    await foto(page, grade, 320, cor);
    fotos.push([feed, grade]);
  }

  const semana = (await (await request.get("/api/v1/eventos?item=P06", { headers: comToken(await token(request, ana.ra, ana.senha)) })).json())[0].id;
  const materias = await (await request.get("/api/v1/eu/materias", { headers: comToken(await token(request, carla.ra, carla.senha)) })).json();
  const bancoDeDados = materias.find((m: { nome: string }) => m.nome === "Banco de Dados").id;

  const daAna = await token(request, ana.ra, ana.senha);
  const premioDaAna = await reivindicar(request, daAna, {
    item: "P06", eventoId: semana, uploadId: await upload(request, daAna, ...fotos[0]!), legenda: "Cinco dias de semana acadêmica!",
  });
  const doBruno = await token(request, bruno.ra, bruno.senha);
  await reivindicar(request, doBruno, {
    item: "P01",
    eventoDigitado: { nome: "Palestra de LGPD", inicio: "2026-11-03", fim: "2026-11-03" },
    uploadId: await upload(request, doBruno, ...fotos[1]!),
    legenda: "Palestra obrigatória do curso.",
  });
  const daCarla = await token(request, carla.ra, carla.senha);
  await reivindicar(request, daCarla, {
    item: "P17",
    eventoDigitado: { nome: "Seminário de normalização", inicio: "2026-11-05", fim: "2026-11-05" },
    materiaId: bancoDeDados,
    uploadId: await upload(request, daCarla, ...fotos[2]!),
  });

  // A da Ana chegou há 8 dias: a marca aparece.
  sql(`UPDATE comprovacao SET criada_em = now() - interval '8 days' WHERE premio_participacao_id = '${premioDaAna}';`);

  await page.goto("/login");
  await page.getByLabel("RA ou e-mail").fill(professora.email);
  await page.getByLabel("Senha", { exact: true }).fill(professora.senha);
  await page.getByRole("button", { name: "Entrar", exact: true }).click();
  await page.getByRole("tab", { name: "Perfil" }).click();
  await page.getByRole("button", { name: "Menu" }).click();
  await page.getByRole("button", { name: "Comprovações" }).click();

  await page.setViewportSize({ width: 390, height: 1500 });
  const primeira = page.locator('[data-testid^="comprovacao-"]').first();
  await expect(primeira.getByTestId("marca-mais-de-7-dias")).toBeVisible();
  for (const imagem of await page.getByTestId("foto-da-comprovacao").locator("img").all()) {
    await expect.poll(() => imagem.evaluate((img: HTMLImageElement) => img.naturalWidth)).toBeGreaterThan(0);
  }
  await page.screenshot({ path: `${SAIDA}/comprovacoes-${tema}.png` });

  await page.setViewportSize({ width: 390, height: 844 });
  await page.getByRole("button", { name: "Reprovar a comprovação de Ana Souza" }).click();
  const folha = page.getByTestId("folha-de-motivo");
  await folha.getByLabel("Motivo").fill("A foto não mostra a semana acadêmica. Mande outra, com o crachá ou o palco.");
  await page.screenshot({ path: `${SAIDA}/folha-reprovar-${tema}.png` });
});

