  const primeira = page.locator('[data-testid^="comprovacao-"]').first();
  await expect(primeira.getByTestId("marca-mais-de-7-dias")).toBeVisible();
  for (const imagem of await page.getByTestId("foto-da-comprovacao").locator("img").all()) {
    await expect.poll(() => imagem.evaluate((img: HTMLImageElement) => img.naturalWidth)).toBeGreaterThan(0);
  }
  await page.screenshot({ path: `${SAIDA}/comprovacoes-${tema}.png` });

  await page.setViewportSize({ width: 390, height: 844 });
  await page.getByRole("button", { name: "Reprovar a comprovação de Ana Souza" }).click();
  const folha = page.getByTestId("folha-de-motivo");
